// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warpTime, uint256 blockNum) public {
        vm.assume(amount == 10 ether);
        address caller = address(0xdead);
        vm.deal(caller, amount);
        vm.assume(warpTime > 0);
        vm.warp(warpTime);
        vm.roll(blockNum);
        uint256 balanceBefore = caller.balance;
        vm.prank(caller);
        (bool ok,) = address(c).call{value: amount}("");
        if (ok) {
            if (blockNum % 15 == 0) {
                assertTrue(caller.balance == balanceBefore - amount + address(c).balance + amount);
            }
        }
    }
}
